<!doctype html>
<html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Kiểm tra hồ sơ vay</title>
<style>
*{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center;padding:24px;background:#f8fafc;font-family:Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:#172033}.card{width:min(100%,460px);text-align:center}.scene{position:relative;width:190px;height:176px;margin:auto}.glow{position:absolute;width:145px;height:145px;left:50%;top:48%;transform:translate(-50%,-50%);border-radius:50%;background:#eff6ff;animation:glow 2.2s ease-in-out infinite}.shadow{position:absolute;width:104px;height:14px;left:50%;bottom:16px;transform:translateX(-50%);border-radius:50%;background:#0f172214;filter:blur(7px)}.paper{position:absolute;width:94px;height:122px;left:48px;top:18px;border-radius:14px;border:2px solid #cbd5e1;background:#fff;box-shadow:0 24px 48px #0f17221a;overflow:hidden;animation:float 2.8s ease-in-out infinite}.paper:before{content:"";position:absolute;left:18px;top:29px;width:56px;height:5px;border-radius:5px;background:#bfdbfe;box-shadow:0 16px #dbeafe,0 32px #dbeafe}.scan{position:absolute;left:0;width:100%;height:38px;background:linear-gradient(transparent,#3b82f62e,transparent);animation:scan 2.3s ease-in-out infinite}.badge{position:absolute;right:-10px;bottom:-8px;width:40px;height:40px;display:grid;place-items:center;border-radius:50%;background:#fff;border:1px solid #dbeafe;box-shadow:0 8px 18px #2563eb29;color:#2563eb;font-weight:900;animation:pulse 1.1s ease-in-out infinite}.result{display:none;position:absolute;z-index:2;left:50%;top:51%;transform:translate(-50%,-50%);width:82px;height:82px;border:2px solid;border-radius:50%;place-items:center;font-size:50px;font-weight:800;box-shadow:0 12px 30px #0f17221a}.status{font-size:22px;font-weight:800;color:#334155;margin-top:4px}.status-dot{display:inline-block;width:8px;height:8px;border-radius:50%;background:#3b82f6;box-shadow:0 0 0 5px #3b82f61f;margin-right:9px}.desc{margin:10px auto 0;max-width:360px;font-size:14px;line-height:1.65;color:#64748b}.progress{width:180px;height:4px;margin:20px auto 0;border-radius:10px;background:#e8eef7;overflow:hidden}.progress-bar{width:38%;height:100%;border-radius:inherit;background:#3b82f6;animation:progress 2.2s ease-in-out infinite}.back{display:inline-block;margin-top:24px;color:#2563eb;text-decoration:none;font-size:14px;font-weight:700}.success .glow{background:#ecfdf5}.success .paper{border-color:#86efac}.success .result{display:grid;color:#15803d;border-color:#86efac;background:#fff}.success .status{color:#15803d}.success .status-dot{background:#22c55e;box-shadow:0 0 0 5px #22c55e1f}.failed .glow{background:#fff7ed}.failed .paper{border-color:#fdba74;animation:sad .65s ease-in-out 1}.failed .result{display:grid;color:#c2410c;border-color:#fdba74;background:#fff}.failed .status{color:#c2410c}.failed .status-dot{background:#f97316;box-shadow:0 0 0 5px #f973161f}@keyframes float{50%{transform:translateY(-6px)}}@keyframes scan{0%{transform:translateY(-42px);opacity:0}15%,75%{opacity:1}100%{transform:translateY(132px);opacity:0}}@keyframes pulse{50%{transform:scale(1.12);opacity:.65}}@keyframes progress{0%{transform:translateX(-150%)}100%{transform:translateX(400%)}}@keyframes glow{50%{transform:translate(-50%,-50%) scale(1.06);opacity:.72}}@keyframes sad{20%{transform:translateX(-6px)}40%{transform:translateX(6px)}60%{transform:translateX(-4px)}80%{transform:translateX(3px)}}
</style></head><body>
<main class="card" id="app"><div class="scene"><div class="glow"></div><div class="shadow"></div><div class="paper"><div class="scan"></div><div class="badge">…</div></div><div class="result" id="result"></div></div><div class="status" id="title"><span class="status-dot"></span>Đang xử lý hồ sơ</div><p id="message" class="desc">Hệ thống đang kiểm tra thông tin của bạn...</p><div class="progress" id="progress"><div class="progress-bar"></div></div><p class="desc" style="font-size:12px">Loading... Vui lòng chờ 1–2 giây. Nếu đủ điều kiện, hệ thống sẽ chuyển đến FEOL bằng Deeplink.</p><a class="back" href="{{ url('/') }}">Quay về trang chủ</a></main>
<script>
(()=>{const url=@json($statusUrl),app=document.getElementById('app'),title=document.getElementById('title'),message=document.getElementById('message'),result=document.getElementById('result'),progress=document.getElementById('progress');let running=false,done=false;const display=(state)=>{app.classList.remove('success','failed');if(state==='eligible'){app.classList.add('success');result.textContent='✓';title.innerHTML='<span class="status-dot"></span>Chúc mừng!';message.textContent='Hồ sơ Khách hàng thoả mãn điều kiện đăng ký hồ sơ vay.';progress.hidden=true;return}app.classList.add('failed');result.textContent='☹';title.innerHTML='<span class="status-dot"></span>Rất tiếc!';message.textContent='Hồ sơ của Khách hàng không thoả điều kiện.';progress.hidden=true};const check=async()=>{if(running||done)return;running=true;try{const response=await fetch(url,{headers:{Accept:'application/json'},cache:'no-store'});if(!response.ok)throw new Error('status_http_'+response.status);const data=await response.json();if(data.state==='eligible'&&data.redirect_url){display('eligible');done=true;window.setTimeout(()=>window.location.replace(data.redirect_url),900);return}if(data.state==='completed'){display('failed');done=true;return}message.textContent='Hệ thống đang kiểm tra thông tin của bạn...'}catch(_){message.textContent='Hệ thống đang kết nối lại. Vui lòng chờ trong giây lát.'}finally{running=false}window.setTimeout(check,2000)};check()})();
</script></body></html>
